B.aed=new A.dw("\u041a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u043e\u0440","\u0437\u043d\u0430\u0435\u0442, \u043a\u0430\u043a \u043a\u043e\u043c\u0431\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0437\u043b\u0438\u0447\u043d\u044b\u0435 \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b, \u0447\u0442\u043e\u0431\u044b \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u043d\u0435\u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0443\u0435\u043c\u044b\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u044b. \u0420\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0441 \u0430\u043b\u0445\u0438\u043c\u0438\u0435\u0439, \u0447\u0442\u043e\u0431\u044b \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u043d\u0430\u0434\u043e\u0431\u044c\u044f \u0438 \u044d\u043b\u0438\u043a\u0441\u0438\u0440\u044b.",!0,!1)
B.ael=new A.dw("\u041e\u0445\u043e\u0442\u043d\u0438\u043a \u0437\u0430 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430\u043c\u0438","\u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u043e\u0438\u0441\u043a\u0435 \u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0438 \u0434\u0440\u0435\u0432\u043d\u0438\u0445 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u0432. \u0412\u043b\u0430\u0434\u0435\u043d\u0438\u0435 \u0437\u043d\u0430\u043d\u0438\u044f\u043c\u0438 \u043e\u0431 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0438 \u044f\u0437\u044b\u043a\u0430\u0445 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u0432 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u0439 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 \u043d\u0430\u0445\u043e\u0434\u043e\u043a.",!1,!1)
B.aea=new A.dw("\u041c\u0430\u0441\u0442\u0435\u0440\u0438\u0446\u0430 \u043f\u043e \u0431\u043e\u0435\u0432\u044b\u043c \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0430\u043c","\u0441\u043e\u0447\u0435\u0442\u0430\u0435\u0442 \u0431\u043e\u0435\u0432\u0443\u044e \u043c\u0430\u0433\u0438\u044e \u0438 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0443, \u043e\u0431\u0443\u0447\u0430\u044f \u0434\u0440\u0443\u0433\u0438\u0445 \u043e\u0441\u043d\u043e\u0432\u0430\u043c \u0441\u0430\u043c\u043e\u043e\u0431\u043e\u0440\u043e\u043d\u044b \u0438 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u043e\u0440\u0438\u043a\u0435 \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u0439.",!1,!1)
B.ae3=new A.dw("\u0422\u0440\u0430\u043a\u0442\u0438\u0440\u0449\u0438\u043a","\u0441\u043e\u0437\u0434\u0430\u0435\u0442 \u0432\u043e\u043b\u0448\u0435\u0431\u043d\u044b\u0435 \u0438\u043b\u043b\u044e\u0437\u0438\u0438 \u0434\u043b\u044f \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432 \u0432 \u0441\u0432\u043e\u0439 \u0442\u0440\u0430\u043a\u0442\u0438\u0440. \u041c\u043e\u0436\u0435\u0442 \u043e\u0431\u0443\u0447\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0445 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0443 \u0438\u043b\u043b\u044e\u0437\u0438\u0439 \u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u043c\u0430\u0433\u0438\u0438 \u0434\u043b\u044f \u0440\u0430\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f.",!1,!1)
B.aec=new A.dw("\u041c\u0430\u0433\u043e\u0438\u0441\u0442","\u0438\u0437\u0443\u0447\u0430\u0435\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u043c\u0430\u0433\u0438\u0435\u0439 \u0438 \u044d\u043c\u043e\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435\u043c \u0441\u0443\u0449\u0435\u0441\u0442\u0432, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u0437\u0430\u0433\u043e\u0432\u043e\u0440\u044b, \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0430\u0445 \u0438 \u044d\u043c\u043e\u0446\u0438\u044f\u0445.",!1,!1)
B.ae5=new A.dw("\u041a\u0430\u043c\u043d\u0435\u0440\u0435\u0437-\u0440\u0443\u043d\u043e\u043b\u043e\u0433","\u041c\u0430\u0441\u0442\u0435\u0440 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0440\u0430\u0433\u043e\u0446\u0435\u043d\u043d\u044b\u0445 \u0438 \u043f\u043e\u0434\u0435\u043b\u043e\u0447\u043d\u044b\u0445 \u043a\u0430\u043c\u043d\u0435\u0439. \u041c\u044b \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0433\u0440\u0430\u043d\u0438\u043c \u0441\u0430\u043c\u043e\u0446\u0432\u0435\u0442\u044b, \u0430 \u0432\u044b\u0441\u0435\u043a\u0430\u0435\u043c \u043d\u0430 \u043d\u0438\u0445 \u0440\u0443\u043d\u044b, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u043d\u0435-\u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 (\u043d\u043e \u0440\u0435\u0437\u043e\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0435 \u0441 \u043c\u0430\u0433\u0438\u0435\u0439) \u043d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u0438 \u0438\u043b\u0438 \u043a\u043b\u044e\u0447\u0438-\u0430\u043a\u0442\u0438\u0432\u0430\u0442\u043e\u0440\u044b \u0434\u043b\u044f \u0434\u0432\u0435\u043b\u0435\u0439 \u0438 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u043e\u0432. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u043d\u0430\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c, \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0449\u0443\u044e \u043d\u0430 \u0433\u043b\u0430\u0437 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0442\u044c \u043f\u0443\u0441\u0442\u043e\u0442\u044b \u0432 \u0441\u043a\u0430\u043b\u0430\u0445 \u0438\u043b\u0438 \u0441\u043b\u0430\u0431\u044b\u0435 \u043c\u0435\u0441\u0442\u0430 \u0432 \u043a\u0430\u043c\u0435\u043d\u043d\u044b\u0445 \u0433\u043e\u043b\u0435\u043c\u0430\u0445.",!0,!1)
B.ae_=new A.dw("\u041a\u043e\u0441\u0442\u043e\u0440\u0435\u0437","\u0421\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442 \u043f\u043e \u0440\u0430\u0431\u043e\u0442\u0435 \u0441 \u043a\u043e\u0441\u0442\u044f\u043c\u0438, \u0440\u043e\u0433\u0430\u043c\u0438 \u0438 \u0445\u0438\u0442\u0438\u043d\u043e\u043c \u043c\u043e\u043d\u0441\u0442\u0440\u043e\u0432. \u0417\u043d\u0430\u0435\u0442, \u043a\u0430\u043a \u0438\u0437\u0432\u043b\u0435\u0447\u044c \u0438\u0437 \u043e\u0441\u0442\u0430\u043d\u043a\u043e\u0432 \u0442\u0432\u0430\u0440\u0438 \u0435\u0451 \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u0443\u044e \u0441\u0438\u043b\u0443, \u043d\u0435 \u043f\u0440\u0438\u0431\u0435\u0433\u0430\u044f \u043a \u043d\u0435\u043a\u0440\u043e\u043c\u0430\u043d\u0442\u0438\u0438. \u041c\u044b \u0441\u043e\u0437\u0434\u0430\u0435\u043c \u0430\u043c\u0443\u043b\u0435\u0442\u044b, \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u044e\u0449\u0438\u0435 \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0438\u043d\u043a\u0442\u044b, \u0438\u043b\u0438 \u0434\u043e\u0441\u043f\u0435\u0445\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0435 \u0431\u0440\u0435\u043d\u0447\u0430\u0442. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0442\u044c\u0441\u044f \u0434\u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u043a\u043e\u0441\u0442\u044f\u043d\u044b\u0445 \u043f\u0440\u043e\u0442\u0435\u0437\u043e\u0432, \u0441\u0440\u0430\u0441\u0442\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u0441 \u043f\u043b\u043e\u0442\u044c\u044e.",!0,!0)
B.adY=new A.dw("\u0422\u043a\u0430\u0447 \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043d\u0438\u0442\u0435\u0439",'\u041d\u0435 \u043f\u0443\u0442\u0430\u0442\u044c \u0441 \u043f\u043e\u0440\u0442\u043d\u044b\u043c. \u041c\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u043c \u0441 \u0441\u044b\u0440\u043e\u0439 \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0438\u0435\u0439, \u0441\u043f\u043b\u0435\u0442\u0430\u044f \u0435\u0451 \u0432 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043d\u0438\u0442\u0438, \u0448\u043d\u0443\u0440\u044b \u0438\u043b\u0438 \u0432\u0435\u0440\u0435\u0432\u043a\u0438. \u0418\u0437 \u043d\u0430\u0448\u0438\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u043c\u043e\u0436\u043d\u043e \u0441\u0432\u044f\u0437\u0430\u0442\u044c \u043f\u043b\u0430\u0449, \u0433\u0430\u0441\u044f\u0449\u0438\u0439 \u0438\u043d\u0435\u0440\u0446\u0438\u044e \u043f\u0430\u0434\u0435\u043d\u0438\u044f, \u0438\u043b\u0438 \u0441\u043f\u043b\u0435\u0441\u0442\u0438 \u0432\u0435\u0440\u0435\u0432\u043a\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0441\u0430\u043c\u0430 \u043e\u0431\u043e\u0432\u044c\u0435\u0442\u0441\u044f \u0432\u043e\u043a\u0440\u0443\u0433 \u0431\u0430\u043b\u043a\u0438. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 "\u0441\u0435\u0442\u0435\u0439 \u0442\u0438\u0448\u0438\u043d\u044b" \u0438\u043b\u0438 "\u0442\u043a\u0430\u043d\u0438 \u0437\u0430\u0431\u0432\u0435\u043d\u0438\u044f".',!0,!0)
B.ae8=new A.dw("\u041e\u0433\u0440\u0430\u043d\u0449\u0438\u043a \u043b\u0438\u043d\u0437","\u041e\u043f\u0442\u0438\u043a \u0438 \u0441\u0442\u0435\u043a\u043b\u043e\u0434\u0443\u0432, \u0441\u043e\u0437\u0434\u0430\u044e\u0449\u0438\u0439 \u043b\u0438\u043d\u0437\u044b \u0434\u043b\u044f \u043f\u043e\u0434\u0437\u043e\u0440\u043d\u044b\u0445 \u0442\u0440\u0443\u0431, \u043e\u0447\u043a\u043e\u0432 \u0438 \u043c\u0430\u044f\u043a\u043e\u0432. \u041c\u044b \u0443\u043c\u0435\u0435\u043c \u0448\u043b\u0438\u0444\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0435\u043a\u043b\u043e \u0442\u0430\u043a, \u0447\u0442\u043e \u043e\u043d\u043e \u0444\u043e\u043a\u0443\u0441\u0438\u0440\u0443\u0435\u0442 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0432\u0435\u0442, \u043d\u043e \u0438 \u0432\u0437\u0433\u043b\u044f\u0434 (\u0447\u0430\u0440\u044b \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u044f) \u0438\u043b\u0438 \u043b\u0443\u0447\u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438. \u0412 \u043e\u0442\u043b\u0438\u0447\u0438\u0435 \u043e\u0442 \u0413\u0440\u0435\u043c\u0438\u043a\u0430 (\u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430), \u043c\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u043c \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e \u0441 \u043e\u043f\u0442\u0438\u043a\u043e\u0439 \u0438 \u043f\u0440\u0435\u043b\u043e\u043c\u043b\u0435\u043d\u0438\u0435\u043c \u043c\u0430\u0433\u0438\u0438 \u0447\u0435\u0440\u0435\u0437 \u0441\u0442\u0435\u043a\u043b\u043e. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0442\u044c \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u043b\u0438\u043d\u0437, \u0432\u0438\u0434\u044f\u0449\u0438\u0445 \u043d\u0435\u0432\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u0438\u043b\u0438 \u0447\u0443\u0436\u0438\u0435 \u044d\u043c\u043e\u0446\u0438\u0438.",!0,!1)
B.aen=new A.dw("\u041c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433-\u0430\u043b\u0445\u0438\u043c\u0438\u043a",'\u041f\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u043d\u0430\u044f \u043f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u043a\u0443\u0437\u043d\u0435\u0439 \u0438 \u0430\u043b\u0445\u0438\u043c\u0438\u0435\u0439. \u041c\u044b \u043d\u0435 \u043a\u0443\u0435\u043c \u043c\u0435\u0447\u0438 (\u044d\u0442\u043e \u0434\u0435\u043b\u043e \u043a\u0443\u0437\u043d\u0435\u0446\u0430), \u0430 \u0441\u043e\u0437\u0434\u0430\u0435\u043c \u0441\u043f\u043b\u0430\u0432\u044b \u0441 \u043f\u0430\u0440\u0430\u0434\u043e\u043a\u0441\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u043c\u0438: \u0436\u0438\u0434\u043a\u0438\u0439 \u043c\u0435\u0442\u0430\u043b\u043b, \u0442\u0432\u0435\u0440\u0434\u044b\u0439 \u043a\u0430\u043a \u0441\u0442\u0430\u043b\u044c \u043f\u0440\u0438 \u0443\u0434\u0430\u0440\u0435; "\u043a\u0440\u0438\u0447\u0430\u0449\u0438\u0439" \u043c\u0435\u0442\u0430\u043b\u043b, \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u043d\u0430 \u044f\u0434; \u0438\u043b\u0438 \u0440\u0436\u0430\u0432\u0447\u0438\u043d\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043b\u0435\u0447\u0438\u0442, \u0430 \u043d\u0435 \u0440\u0430\u0437\u044a\u0435\u0434\u0430\u0435\u0442. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u043d\u0430\u0432\u044b\u043a\u0438 \u043b\u0435\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 \u043f\u0440\u044f\u043c\u043e \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043f\u043b\u0430\u0432\u043a\u0438.',!0,!1)
B.ae4=new A.dw("\u0422\u0430\u043a\u0441\u0438\u0434\u0435\u0440\u043c\u0438\u0441\u0442 \u0437\u0430\u043f\u0430\u0445\u043e\u0432",'\u041c\u044b \u2014 \u043e\u0445\u043e\u0442\u043d\u0438\u043a\u0438 \u0437\u0430 \u0430\u0440\u043e\u043c\u0430\u0442\u0430\u043c\u0438. \u0423\u043c\u0435\u0435\u043c \u0437\u0430\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0437\u0430\u043f\u0430\u0445 \u0441\u0442\u0440\u0430\u0445\u0430, \u0440\u0430\u0434\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0433\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u0432 \u043a\u043e\u043b\u0431\u0443, \u0430 \u043f\u043e\u0437\u0436\u0435 \u0432\u044b\u043f\u0443\u0441\u043a\u0430\u0442\u044c \u0435\u0433\u043e \u0434\u043b\u044f \u043e\u0431\u043c\u0430\u043d\u0430 \u0447\u0443\u0434\u043e\u0432\u0438\u0449 \u0438\u043b\u0438 \u0441\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u043c\u0430\u043d\u0438\u043f\u0443\u043b\u044f\u0446\u0438\u0439. \u041d\u0435 \u0438\u043b\u043b\u044e\u0437\u0438\u044f, \u0430 \u0447\u0438\u0441\u0442\u0430\u044f \u0445\u0438\u043c\u0438\u044f \u0438 \u0441\u0435\u043d\u0441\u043e\u0440\u0438\u043a\u0430. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0442\u044c\u0441\u044f \u0434\u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f "\u0432\u043e\u043d\u044e\u0447\u0438\u0445 \u0431\u043e\u043c\u0431" \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u0444\u0435\u0440\u043e\u043c\u043e\u043d\u043e\u0432 \u043c\u043e\u043d\u0441\u0442\u0440\u043e\u0432, \u0432\u044b\u0437\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u0443 \u043d\u0438\u0445 \u0436\u0435 \u043f\u0430\u043d\u0438\u043a\u0443 \u0438\u043b\u0438 \u0430\u0433\u0440\u0435\u0441\u0441\u0438\u044e \u0432 \u043d\u0443\u0436\u043d\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443.',!1,!0)
B.aem=new A.dw("\u0421\u043d\u043e\u0432\u0438\u0434\u0435\u0446",'\u0421\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442 \u043f\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u044b\u043c \u0441\u043d\u043e\u0432\u0438\u0434\u0435\u043d\u0438\u044f\u043c. \u041c\u044b \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0441\u043f\u0438\u043c, \u0430 \u043f\u0443\u0442\u0435\u0448\u0435\u0441\u0442\u0432\u0443\u0435\u043c \u043f\u043e \u0441\u043b\u043e\u044f\u043c \u0441\u043d\u0430, \u0432\u044b\u043b\u0430\u0432\u043b\u0438\u0432\u0430\u044f \u043e\u0442\u0442\u0443\u0434\u0430 \u043f\u0440\u0435\u0434\u0437\u043d\u0430\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u0438\u044f \u0438\u043b\u0438, \u043f\u0440\u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u043f\u0440\u043e\u043a\u0430\u0447\u043a\u0435, \u0437\u0430\u0431\u0438\u0440\u0430\u044f\u0441\u044c \u0432 \u0447\u0443\u0436\u0438\u0435 \u043a\u043e\u0448\u043c\u0430\u0440\u044b, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u043e\u0434\u0441\u043e\u0437\u043d\u0430\u043d\u0438\u0435 \u0441\u043f\u044f\u0449\u0435\u0433\u043e. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0442\u044c \u043d\u0430\u0432\u044b\u043a "\u041e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u043e\u0435 \u0437\u0430\u0431\u044b\u0442\u044c\u0451", \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0449\u0438\u0439 \u0441\u043f\u0430\u0442\u044c \u0432 \u0431\u043e\u044e \u0434\u043b\u044f \u0440\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u043c\u0430\u043d\u044b \u0441 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u043c\u0438 \u0433\u043b\u0430\u0437\u0430\u043c\u0438, \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043f\u0440\u044f\u043c\u0443\u044e \u0443\u0433\u0440\u043e\u0437\u0443.',!1,!0)
B.ae2=new A.dw("\u042d\u0445\u043e-\u043b\u043e\u043a\u0430\u0442\u043e\u0440",'\u0421\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442 \u043f\u043e \u0440\u0430\u0431\u043e\u0442\u0435 \u0441 \u043f\u0440\u043e\u0448\u043b\u044b\u043c \u0447\u0435\u0440\u0435\u0437 \u0437\u0432\u0443\u043a. \u041c\u044b \u0441\u043b\u044b\u0448\u0438\u043c \u043d\u0435 \u0443\u0448\u0430\u043c\u0438, \u0430 "\u043a\u043e\u0441\u0442\u044f\u043c\u0438". \u041f\u0440\u0438\u0441\u043b\u043e\u043d\u0438\u0432\u0448\u0438\u0441\u044c \u043a \u0441\u0442\u0435\u043d\u0435 \u0440\u0443\u0438\u043d, \u043c\u043e\u0436\u0435\u043c \u0443\u043b\u043e\u0432\u0438\u0442\u044c \u044d\u0445\u043e \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430, \u0447\u0442\u043e \u0437\u0432\u0443\u0447\u0430\u043b \u0437\u0434\u0435\u0441\u044c \u0432\u0435\u043a\u0430 \u043d\u0430\u0437\u0430\u0434. \u041d\u0435 \u043f\u0443\u0442\u0430\u0442\u044c \u0441 \u041e\u0445\u043e\u0442\u043d\u0438\u043a\u043e\u043c \u043f\u043e \u0441\u043b\u0435\u0434\u0430\u043c (\u0442\u043e\u0442 \u0438\u0434\u0435\u0442 \u043f\u043e \u0441\u0432\u0435\u0436\u0435\u043c\u0443 \u0441\u043b\u0435\u0434\u0443), \u043c\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u043c \u043a\u0430\u0440\u0442\u0438\u043d\u0443 \u0441\u043e\u0431\u044b\u0442\u0438\u0439 \u0447\u0435\u0440\u0435\u0437 \u0430\u043a\u0443\u0441\u0442\u0438\u043a\u0443 \u0438 \u0432\u0438\u0431\u0440\u0430\u0446\u0438\u0438. \u041c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0432\u0438\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u0433\u043b\u0443\u0448\u0435\u043d\u0438\u044f \u0432\u0440\u0430\u0433\u043e\u0432 \u0438\u043d\u0444\u0440\u0430\u0437\u0432\u0443\u043a\u043e\u043c \u0441 \u043e\u0442\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c.',!1,!0)
